pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testRegression_property() public {
        address unauthorized = address(0x1234);
        vm.prank(unauthorized);
        bool result = c.logRedemptionRequested(address(0), bytes32(0), 0, "", 0, "");
        assertTrue(result == false);
    }
}
